INSERT INTO zoho_import.notes ("note_record_id", "person_type", "person_record_id", "person_name", "note_title", "note_content", "note_owner", "created_by", "created_time", "modified_time") VALUES
  ('zcrm_1579374000158462019', 'contact', 'zcrm_1579374000056599004', 'Adam Davis', NULL, '1-31-25 Cheryl 303-956-5470 called for Adam and left a vm to run the card again ending in 2001. Adam also sent me an email and a text to make sure to run the card. The balance is paid down and should work again. I sent the emails to Patti and just tried calling her. Went to vm. I''m going to send a note on Teams.', 'Wendy Scipione - SR VP National Sales Advisor', 'Wendy Scipione - SR VP National Sales Advisor', '2025-01-31 11:25:19', '2025-01-31 11:27:50'),
  ('zcrm_1579374000158462014', 'contact', 'zcrm_1579374000065104032', 'Clove Berger', NULL, '1-31-25 Clove called bc she needs to submit a Need with Zion for her daughter''s lower back pain health issue and is still collecting the bills which has been tough. UC Health is making it difficult but she thinks they''re going to send it today. I let her know about the 6 month limit and to open the Need immediately. She will do that and upload everything she has so far. The first visit was at the end of July. She''s aware that one might not be shared. She also asked about prescriptions and her desired pharmacy for her daughter in CA and for her here no longer will deliver to their homes. I told her to call the MPB Concierge for help with that. They might be able to find a mail-order solution for each of them. All set for now!', 'Wendy Scipione - SR VP National Sales Advisor', 'Wendy Scipione - SR VP National Sales Advisor', '2025-01-31 11:21:53', '2025-01-31 11:21:53'),
